mapper.select:
select 
from content.content_item c join source.source_entity s on s.id = c.source_entity_id
where 
  and (c.search_tsv @@ websearch_to_tsquery('simple', #{query})
       or lower(coalesce(c.title_zh, '') || ' ' || coalesce(c.original_title, '') || ' ' || coalesce(c.summary_zh, '')) like '%' || lower(#{query}) || '%')
and c.source_type = #{sourceType}
and c.content_type = #{contentType}
order by ts_rank_cd(c.search_tsv, websearch_to_tsquery('simple', #{query})) desc,
         c.published_at desc, c.id desc
limit #{limit}
